terraform {
  required_version = ">= 1.5.0, < 2.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.63.0, < 7.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
  default_tags {
    tags = local.tags
  }
}

variable "aws_region" {
  type        = string
  description = "AWS Region selected by the immutable Architecture Document."
  default     = "us-east-1"
}

variable "event_s3_image_metadata_artifact_path" {
  type        = string
  description = "Stable relative package output produced by the separate Prompt 32A workload builder."
  default     = "../application/artifacts/workload_event_s3_image_metadata/function.zip"
  validation {
    condition     = can(regex("^\\.\\.?/", var.event_s3_image_metadata_artifact_path))
    error_message = "Package path must be repository-relative and begin with ./ or ../; absolute machine paths are forbidden."
  }
}

variable "stage" {
  type        = string
  description = "Architecture variable stage."
  default     = "test"
}

locals {
  tags = {
    CloudMarkupArchitecture     = "architecture_event_s3_image_metadata"
    CloudMarkupRevision         = "revision_event_s3_image_metadata_1"
    CloudMarkupSolutionRevision = "solution_notes_revision_1"
    ManagedBy                   = "CloudMarkup"
  }
}

resource "aws_lambda_function" "event_s3_image_metadata" {
  function_name                  = "event_s3_image_metadata"
  description                    = "CloudMarkup notes-API workload."
  role                           = aws_iam_role.notes_role.arn
  handler                        = "index.handler"
  runtime                        = "nodejs24.x"
  architectures                  = ["arm64"]
  memory_size                    = 256
  reserved_concurrent_executions = 10
  timeout                        = 30
  filename                       = var.event_s3_image_metadata_artifact_path
  source_code_hash               = filebase64sha256(var.event_s3_image_metadata_artifact_path)
  tracing_config {
    mode = "Active"
  }
  environment {
    variables = {
      "METADATA_TABLE_NAME" = aws_dynamodb_table.image_metadata.name
      "APP_STAGE"           = var.stage
    }
  }
  tags = local.tags
}

resource "aws_dynamodb_table" "image_metadata" {
  name                        = "image-metadata"
  billing_mode                = "PAY_PER_REQUEST"
  hash_key                    = "key"
  deletion_protection_enabled = true
  attribute {
    name = "key"
    type = "S"
  }
  point_in_time_recovery {
    enabled = true
  }
  server_side_encryption {
    enabled = true
  }
  tags = local.tags
}

data "aws_iam_policy_document" "event_logs_policy_s3_image_metadata" {
  statement {
    sid       = "eventlogspolicys3imagemetadata"
    effect    = "Allow"
    actions   = ["logs:CreateLogStream", "logs:PutLogEvents"]
    resources = [format("%s:*", aws_cloudwatch_log_group.event_logs_s3_image_metadata.arn)]
  }
}

data "aws_iam_policy_document" "metadata_write_policy" {
  statement {
    sid       = "metadatawritepolicy"
    effect    = "Allow"
    actions   = ["dynamodb:DeleteItem", "dynamodb:PutItem", "dynamodb:UpdateItem"]
    resources = [aws_dynamodb_table.image_metadata.arn]
  }
}

data "aws_iam_policy_document" "trust_policy" {
  statement {
    sid     = "trustpolicy"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "event_logs_policy_s3_image_metadata" {
  name   = "event_logs_policy_s3_image_metadata"
  role   = aws_iam_role.notes_role.name
  policy = data.aws_iam_policy_document.event_logs_policy_s3_image_metadata.json
}

resource "aws_iam_role_policy" "metadata_write_policy" {
  name   = "metadata_write_policy"
  role   = aws_iam_role.notes_role.name
  policy = data.aws_iam_policy_document.metadata_write_policy.json
}

data "aws_caller_identity" "s3_permission" {
}

resource "aws_lambda_permission" "s3_permission" {
  statement_id   = "s3permission"
  action         = "lambda:InvokeFunction"
  function_name  = aws_lambda_function.event_s3_image_metadata.function_name
  principal      = "s3.amazonaws.com"
  source_arn     = aws_s3_bucket.uploads.arn
  source_account = data.aws_caller_identity.s3_permission.account_id
}

resource "aws_s3_bucket" "uploads" {
  bucket = "cloudmarkup-image-uploads"
  lifecycle {
    prevent_destroy = true
  }
  tags = local.tags
}

resource "aws_s3_bucket_ownership_controls" "uploads_ownership" {
  bucket = aws_s3_bucket.uploads.id
  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "uploads_public" {
  bucket                  = aws_s3_bucket.uploads.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "uploads_encryption" {
  bucket = aws_s3_bucket.uploads.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "uploads_versioning" {
  bucket = aws_s3_bucket.uploads.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_notification" "uploads" {
  bucket = aws_s3_bucket.uploads.id
  lambda_function {
    id                  = aws_lambda_permission.s3_permission.statement_id
    lambda_function_arn = aws_lambda_function.event_s3_image_metadata.arn
    events              = ["s3:ObjectCreated:*"]
    filter_prefix       = "incoming/"
    filter_suffix       = ".jpg"
  }
}

resource "aws_cloudwatch_log_group" "event_logs_s3_image_metadata" {
  name              = "/aws/lambda/notes_handler"
  log_group_class   = "STANDARD"
  retention_in_days = 30
  lifecycle {
    prevent_destroy = true
  }
  tags = local.tags
}
